def find_limits(numbers):
    largest = numbers[0]
    smallest = numbers[0]
    for num in numbers:
        if num > largest:
            largest = num
        if num < smallest:
            smallest = num

    return largest, smallest

def binary_search(nums, val):
    low = 0
    high = len(nums) - 1

    while low <= high:
        mid = (low + high) // 2
        if nums[mid] == val:
            return mid
        elif nums[mid] > val:
            high = mid - 1
        else:
            low = mid + 1
    return -1

def weightedAverage(values, weights):
    sum = 0.0
    for i in range(len(values)):
        sum += values[i] * weights[i]
    return sum/len(values)

